import React, { useState, useEffect } from 'react';
import axios from 'axios';
import ContentManager from '../components/ContentManager';
import './AdminDashboard.css';

function AdminDashboard({ user, onDemoAdminLogin, onLogout }) {
  const [stats, setStats] = useState(null);
  const [users, setUsers] = useState([]);
  const [subscriptions, setSubscriptions] = useState([]);
  const [activeTab, setActiveTab] = useState('overview');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user || user.role !== 'admin') {
      setLoading(false);
      return;
    }

    fetchAdminData();
  }, [user]);

  const fetchAdminData = async () => {
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };

      const [statsRes, usersRes, subsRes] = await Promise.all([
        axios.get('http://localhost:5000/api/admin/stats', { headers }),
        axios.get('http://localhost:5000/api/admin/users', { headers }),
        axios.get('http://localhost:5000/api/admin/subscriptions', { headers }),
      ]);

      setStats(statsRes.data);
      setUsers(usersRes.data);
      setSubscriptions(subsRes.data);
    } catch (error) {
      console.error('Error fetching admin data:', error);
    } finally {
      setLoading(false);
    }
  };

  if (!user || user.role !== 'admin') {
    return (
      <div className="admin-dashboard">
        <div className="wrap">
          <div className="admin-header">
            <h1 className="display">Admin Access</h1>
            <p>Sign in as the demo admin to access the CMS and reporting dashboard.</p>
          </div>
          <div className="admin-content">
            <button className="btn-primary" onClick={onDemoAdminLogin}>Login as Demo Admin</button>
          </div>
        </div>
      </div>
    );
  }

  if (loading) {
    return <div className="admin-loading">Loading...</div>;
  }

  return (
    <div className="admin-dashboard">
      <div className="wrap">
        <div className="admin-header admin-header-row">
          <div>
            <h1 className="display">Admin Dashboard</h1>
            <p>Manage users, subscriptions, and website content.</p>
          </div>
          <button type="button" className="admin-logout" onClick={onLogout}>Logout</button>
        </div>

        <div className="admin-tabs">
          <button className={`tab-btn ${activeTab === 'overview' ? 'active' : ''}`} onClick={() => setActiveTab('overview')}>Overview</button>
          <button className={`tab-btn ${activeTab === 'users' ? 'active' : ''}`} onClick={() => setActiveTab('users')}>Users</button>
          <button className={`tab-btn ${activeTab === 'subscriptions' ? 'active' : ''}`} onClick={() => setActiveTab('subscriptions')}>Subscriptions</button>
          <button className={`tab-btn ${activeTab === 'cms' ? 'active' : ''}`} onClick={() => setActiveTab('cms')}>CMS</button>
        </div>

        {activeTab === 'cms' && (
          <div className="admin-content">
            <ContentManager user={user} />
          </div>
        )}

        {activeTab === 'overview' && stats && (
          <div className="admin-content">
            <div className="stats-grid">
              <div className="stat-card">
                <div className="stat-icon">👥</div>
                <div className="stat-data">
                  <div className="stat-value">{stats.totalUsers}</div>
                  <div className="stat-label">Total Users</div>
                </div>
              </div>

              <div className="stat-card">
                <div className="stat-icon">💰</div>
                <div className="stat-data">
                  <div className="stat-value">${stats.totalRevenue}</div>
                  <div className="stat-label">Total Revenue</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && (
          <div className="admin-content">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Role</th>
                </tr>
              </thead>
              <tbody>
                {users.map((item) => (
                  <tr key={item._id}>
                    <td>{item.name || 'User'}</td>
                    <td>{item.email}</td>
                    <td>{item.role}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'subscriptions' && (
          <div className="admin-content">
            {subscriptions.length === 0 ? (
              <p>No subscriptions yet.</p>
            ) : (
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Plan</th>
                    <th>Customer</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {subscriptions.map((sub) => (
                    <tr key={sub._id}>
                      <td>{sub.plan || 'Basic'}</td>
                      <td>{sub.customerName || 'Customer'}</td>
                      <td>{sub.status || 'Active'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default AdminDashboard;
